solutionCode:
def min_window(s, t):
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    missing = len(need)
    best_start, best_len = 0, len(s) + 1
    left = 0
    for right, ch in enumerate(s):
        if ch in need:
            need[ch] -= 1
            if need[ch] == 0:
                missing -= 1
        if missing == 0:
            while s[left] not in need or need[s[left]] < 0:
                if s[left] in need:
                    need[s[left]] += 1
                left += 1
            if right - left + 1 < best_len:
                best_start, best_len = left, right - left + 1
    return "" if best_len > len(s) else s[best_start:best_start + best_len]

bruteForceCode:
def min_window(s, t):
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    best = ""
    for i in range(len(s)):
        counts = {}
        covered = 0
        for j in range(i, len(s)):
            ch = s[j]
            if ch in need:
                counts[ch] = counts.get(ch, 0) + 1
                if counts[ch] == need[ch]:
                    covered += 1
            if covered == len(need):
                if not best or j - i + 1 < len(best):
                    best = s[i:j + 1]
                break
    return best
